  if (progress >= 0.9999) return vec4(0.0);
  float remaining = 1.0 - progress;
  vec2 cardUv = (worldPos - cardRect.xy) / max(cardRect.zw, vec2(1.0));
  float n = fbm(cardUv * noiseScale + noiseSeed);
  float width = max(burnWidth, 0.0001);
  float softness = max(edgeSoftness, 0.0001);
  float alphaMask = smoothstep(n - width - softness, n - width + softness, remaining);
  float sourceMix = smoothstep(n - softness, n + softness, remaining);
  float hotBand = clamp((1.0 - sourceMix) * alphaMask, 0.0, 1.0);
  float hotCore = smoothstep(0.15, 0.9, hotBand);
  vec3 edgeColor = mix(burnColor.rgb, burnHotColor.rgb, hotCore);
  vec4 result = source;
  result.rgb = mix(edgeColor * source.a, source.rgb, sourceMix);
  result.a *= alphaMask;
  ALPHA_TEST(result);
  return result;
}
